import sys
from collections import defaultdict

sys.setrecursionlimit(10**6)

def dfs(node, parent, graph, distances, times):
    if len(graph[node]) == 1 and parent != -1:
        distances[node] = 0
        return times[node]
    max_distance = 0
    for neighbor, time in graph[node]:
        if neighbor != parent:
            max_distance = max(max_distance, dfs(neighbor, node, graph, distances, times) + time)
    distances[node] = max_distance
    return max_distance

def solve(n, edges, queries):
    graph = defaultdict(list)
    for x, y, v in edges:
        graph[x].append((y, v))
        graph[y].append((x, v))

    distances = {}
    times = {}
    for i in range(1, n + 1):
        if len(graph[i]) == 1:
            times[i] = 0
            dfs(i, -1, graph, distances, times)

    max_distance = max(distances.values())
    result = []
    for l in queries:
        if l >= max_distance:
            result.append(n - 1)
        else:
            result.append(n - bisect_left(sorted(distances.values()), max_distance - l))
    return result

